import {listVendors} from "@/lib/data"; import {verifyVendor} from "@/lib/actions"; import {PageShell,Empty,Status} from "@/lib/page";
export default async function VendorsPage(){let rows:any[]=[];let error="";try{rows=await listVendors()}catch(e:any){error=e.message}return <PageShell title="Vendors" description="Vendor registry, identifiers and bank-account verification history.">{error?<Empty>{error}</Empty>:rows.length===0?<Empty>No vendors have been created yet. Vendors are resolved during invoice intake.</Empty>:<div className="glass overflow-hidden rounded-2xl"><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b border-white/10 text-xs uppercase tracking-wider text-slate-500"><tr>{["Vendor","Tax ID","Contact","Verified","Baseline"].map(h=><th key={h} className="px-5 py-4">{h}</th>)}</tr></thead><tbody>{rows.map(v=><tr key={v.id} className="border-b border-white/5 last:border-0"><td className="px-5 py-4 font-medium text-white">{v.legal_name}<div className="text-xs text-slate-500">{v.registration_id||"No registration ID"}</div></td><td className="px-5 py-4 text-slate-300">{v.tax_id||"—"}</td><td className="px-5 py-4 text-slate-400">{v.contact_email||"—"}</td><td className="px-5 py-4"><form action={verifyVendor}><input type="hidden" name="id" value={v.id}/><input type="hidden" name="verified" value={String(!v.verified)}/><button className="cursor-pointer"><Status value={v.verified?"verified":"unverified"}/></button></form></td><td className="px-5 py-4 text-xs text-slate-500">{v.risk_baseline&&Object.keys(v.risk_baseline).length?JSON.stringify(v.risk_baseline):"Not calculated"}</td></tr>)}</tbody></table></div></div>}</PageShell>}
